function ClockApp() {
 const [now,setNow]=useState(new Date());const [elapsed,setElapsed]=useState(0);const [running,setRunning]=useState(false);const [timer,setTimer]=useState(300);const [left,setLeft]=useState(300);const [timerRunning,setTimerRunning]=useState(false);
 useEffect(()=>{const id=setInterval(()=>{setNow(new Date());if(running)setElapsed(x=>x+1);if(timerRunning)setLeft(x=>Math.max(0,x-1));},1000);return()=>clearInterval(id);},[running,timerRunning]);
 useEffect(()=>{if(left===0&&timerRunning){setTimerRunning(false);}},[left,timerRunning]);
 const mmss=(n:number)=>String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');
 return <div className="clock-app"><div className="clock-hero"><p className="eyebrow">LOCAL TIME</p><strong>{now.toLocaleTimeString([], {hour:'2-digit',minute:'2-digit',second:'2-digit'})}</strong><span>{now.toLocaleDateString([], {weekday:'long',month:'long',day:'numeric',year:'numeric'})}</span></div><div className="clock-tools"><section className="clock-tool-card"><Clock3 size={21}/><b>Stopwatch</b><strong>{mmss(elapsed)}</strong><div className="inline-actions"><button className="primary-button" onClick={()=>setRunning(v=>!v)}>{running?'Pause':'Start'}</button><button className="secondary-button" onClick={()=>{setElapsed(0);setRunning(false);}}>Reset</button></div></section><section className="clock-tool-card"><Clock3 size={21}/><b>Countdown timer</b><strong>{mmss(left)}</strong><label className="timer-set">Minutes <input type="number" min="1" max="180" value={Math.max(1,Math.floor(timer/60))} onChange={e=>{const n=Math.max(1,Math.min(180,+e.target.value||1))*60;setTimer(n);setLeft(n);setTimerRunning(false);}}/></label><div className="inline-actions"><button className="primary-button" onClick={()=>{if(left===0)setLeft(timer);setTimerRunning(v=>!v);}}>{timerRunning?'Pause':'Start'}</button><button className="secondary-button" onClick={()=>{setTimerRunning(false);setLeft(timer);}}>Reset</button></div>{left===0&&<small className="success-text">Timer complete</small>}</section></div><p className="hint">Browser timers may be delayed while a tab is in the background.</p></div>;
}
function Games({scores,setScores}:{scores:Record<string,number>;setScores:(v:Record<string,number>|((p:Record<string,number>)=>Record<string,number>))=>void}) {
 const [game,setGame]=useState<'memory'|'tic'|'snake'>('memory');const [cards,setCards]=useState(()=>shuffle(['🌙','🌙','⭐','⭐','🍀','🍀','🌸','🌸','🌊','🌊','☀️','☀️']));const [flipped,setFlipped]=useState<number[]>([]);const [matched,setMatched]=useState<number[]>([]);const [turns,setTurns]=useState(0);const [tic,setTic]=useState<(string|null)[]>(Array(9).fill(null));const [symbol,setSymbol]=useState('X');const [snake,setSnake]=useState([22,21,20]);const [food,setFood]=useState(67);const [dir,setDir]=useState(1);const [snakeOn,setSnakeOn]=useState(false);
 function shuffle<T>(arr:T[]):T[]{return arr.map(x=>({x,r:Math.random()})).sort((a,b)=>a.r-b.r).map(v=>v.x);}
 useEffect(()=>{if(flipped.length!==2)return;const [a,b]=flipped;if(matched.includes(a)||matched.includes(b))return;if(cards[a]===cards[b]){const next=[...matched,a,b];setMatched(next);if(next.length===cards.length)setScores(s=>({...s,memory:Math.max(s.memory??0,Math.max(0,100-turns*2))}));const t=setTimeout(()=>setFlipped([]),450);return()=>clearTimeout(t);}const t=setTimeout(()=>setFlipped([]),700);return()=>clearTimeout(t);},[flipped,cards,matched.length,turns]);
 useEffect(()=>{if(game!=='snake'||!snakeOn)return;const id=setInterval(()=>{setSnake(s=>{let head=s[0]+dir;if(head<0||head>=100||(dir===1&&head%10===0)||(dir===-1&&head%10===9)||s.includes(head)){setSnakeOn(false);setScores(sc=>({...sc,snake:Math.max(sc.snake??0,s.length-3)}));return s;}if(head===food){setFood(Math.floor(Math.random()*100));return [head,...s];}return [head,...s.slice(0,-1)];});},180);return()=>clearInterval(id);},[game,snakeOn,dir,food]);
 useEffect(()=>{const onKey=(e:KeyboardEvent)=>{if(game!=='snake')return;const map:{[k:string]:number}={ArrowUp:-10,ArrowDown:10,ArrowLeft:-1,ArrowRight:1};const d=map[e.key];if(d&&!(d===10&&dir===-10)&&!(d===-10&&dir===10)&&!(d===1&&dir===-1)&&!(d===-1&&dir===1)){setDir(d);e.preventDefault();}};window.addEventListener('keydown',onKey);return()=>window.removeEventListener('keydown',onKey);},[game,dir]);
 const resetMemory=()=>{setCards(shuffle(['🌙','🌙','⭐','⭐','🍀','🍀','🌸','🌸','🌊','🌊','☀️','☀️']));setMatched([]);setFlipped([]);setTurns(0);};
 const winner=([[0,1,2],[3,4,5],[6,7,8],[0,3,6],[1,4,7],[2,5,8],[0,4,8],[2,4,6]].map(line=>{const mark=tic[line[0]];return mark&&line.every(j=>tic[j]===mark)?mark:null;}).find(Boolean)??null);
 const win=winner!==null;
 const playTic=(i:number)=>{if(tic[i]||win||tic.every(Boolean))return;const next=[...tic];next[i]=symbol;setTic(next);setSymbol(symbol==='X'?'O':'X');if([[0,1,2],[3,4,5],[6,7,8],[0,3,6],[1,4,7],[2,5,8],[0,4,8],[2,4,6]].some(line=>line.every(j=>next[j]===symbol))){setScores(s=>({...s,tic:(s.tic??0)+1}));}};
 return <div className="games-app"><div className="game-tabs">{[['memory','Memory'],['tic','Tic-tac-toe'],['snake','Snake']].map(([id,label])=><button key={id} className={game===id?'active':''} onClick={()=>setGame(id as any)}>{label}</button>)}</div>{game==='memory'&&<div className="game-panel"><div className="game-heading"><div><h2>Memory match</h2><p>Find all six matching pairs.</p></div><span className="score-pill">{matched.length/2}/6 pairs</span></div><div className="memory-grid">{cards.map((c,i)=><button key={i} className={'memory-card '+(matched.includes(i)?'matched':'')} onClick={()=>{if(flipped.length<2&&!matched.includes(i)&&!flipped.includes(i)){setFlipped(f=>[...f,i]);if(flipped.length===1)setTurns(t=>t+1);}}}>{matched.includes(i)||flipped.includes(i)?c:'?'}</button>)}</div><div className="inline-actions"><span className="small-muted">Turns: {turns}</span><button className="secondary-button" onClick={resetMemory}><RotateCcw size={14}/> Restart</button></div></div>}{game==='tic'&&<div className="game-panel"><div className="game-heading"><div><h2>Tic-tac-toe</h2><p>Take turns with a friend on this device.</p></div><span className="score-pill">Wins: {scores.tic??0}</span></div><div className="tic-grid">{tic.map((v,i)=><button key={i} onClick={()=>playTic(i)} className={v==='X'?'x-mark':v==='O'?'o-mark':''}>{v}</button>)}</div><p className="game-result">{win?winner+' wins!':tic.every(Boolean)?'Draw game':symbol+' to play'}</p><button className="secondary-button" onClick={()=>{setTic(Array(9).fill(null));setSymbol('X');}}>Restart</button></div>}{game==='snake'&&<div className="game-panel"><div className="game-heading"><div><h2>Snake</h2><p>Use arrow keys. Avoid edges and your tail.</p></div><span className="score-pill">Best: {scores.snake??0}</span></div><div className="snake-grid">{Array.from({length:100},(_,i)=><span key={i} className={snake.includes(i)?'snake-body':i===food?'snake-food':''}/>)}</div><div className="inline-actions"><button className="primary-button" onClick={()=>{if(snakeOn){setSnakeOn(false);}else{setSnake([22,21,20]);setFood(67);setDir(1);setSnakeOn(true);}}}>{snakeOn?'Pause':'Start / Restart'}</button><span className="small-muted">Score: {snake.length-3}</span></div></div>}</div>;
}
function SettingsApp({prefs,changePrefs,reset}:{prefs:Prefs;changePrefs:(p:Partial<Prefs>)=>void;reset:()=>void}) {
 return <div className="settings-app"><div className="settings-sidebar"><div className="settings-profile"><div className="profile-dot large">{(prefs.username||'G').slice(0,1).toUpperCase()}</div><div><b>{prefs.username||'Guest'}</b><small>Local profile</small></div></div>{[['System','Appearance and desktop'],['Personalization','Color and wallpaper'],['Accessibility','Motion and contrast'],['Storage','Browser data']].map(([h,s])=><div className="settings-nav" key={h}><b>{h}</b><small>{s}</small></div>)}</div><div className="settings-content"><p className="eyebrow">PERSONALIZATION</p><h2>Settings</h2><p>Customize your local desktop experience.</p><section className="setting-card"><h3>Appearance</h3><div className="setting-row"><div><b>Theme</b><small>Change the overall interface</small></div><select value={prefs.theme} onChange={e=>changePrefs({theme:e.target.value as Prefs['theme']})}><option value="dark">Dark</option><option value="light">Light</option><option value="system">System</option></select></div><div className="setting-row"><div><b>Accent color</b><small>Buttons, focus and highlights</small></div><div className="accent-picker">{['#8c94ff','#56c8ec','#50c99b','#f0ae73','#ec84ac','#bd94ff'].map(c=><button key={c} style={{background:c}} className={prefs.accent===c?'chosen':''} onClick={()=>changePrefs({accent:c})} aria-label={'Use accent '+c}/>)}</div></div><div className="setting-row"><div><b>Wallpaper</b><small>Desktop background style</small></div><div className="wallpaper-options">{[['aurora','Aurora'],['dusk','Dusk'],['minimal','Minimal']].map(([v,l])=><button key={v} className={prefs.wallpaper===v?'chosen':''} onClick={()=>changePrefs({wallpaper:v})}><span className={'wallpaper-swatch wallpaper-'+v}/>{l}</button>)}</div></div><div className="setting-row"><div><b>Taskbar translucency</b><small>Adjust the floating panel surface</small></div><label className="range-inline"><input type="range" min="45" max="100" value={prefs.transparency} onChange={e=>changePrefs({transparency:+e.target.value})}/>{prefs.transparency}%</label></div></section><section className="setting-card"><h3>Accessibility and profile</h3><div className="setting-row"><div><b>Reduce motion</b><small>Keep transitions subtle</small></div><input type="checkbox" checked={!prefs.motion} onChange={e=>changePrefs({motion:!e.target.checked})}/></div><div className="setting-row"><div><b>Desktop name</b><small>Displayed in the Start menu</small></div><input className="profile-input" maxLength={24} value={prefs.username} onChange={e=>changePrefs({username:e.target.value})}/></div></section><section className="setting-card"><h3>Storage and recovery</h3><p className="hint">Notes, events, spreadsheet content, game scores and simulated files remain in browser storage on this device. Clearing browser site data can remove them.</p><button className="danger-button" onClick={reset}><Trash2 size={15}/> Reset AeroShell data</button></section><p className="hint"><ShieldCheck size={14}/> No account or remote API is required. Simulated Wi-Fi, volume and airplane controls do not alter real system settings.</p></div></div>;
}
